1	// GET /cards, /sets, /series — the public catalog read API (§6).
2	//
3	// Every route: KV cache-aside middleware first (./cache.ts), query params
4	// validated with @hono/zod-validator (invalid → terse 400 JSON), Drizzle
5	// over D1, and the outgoing payload parsed through the canonical domain
6	// schemas at the boundary (the /health pattern) so row/schema drift fails
7	// loudly instead of leaking. Paired queries (page + count, set + its cards)
8	// go through db.batch() — one D1 round trip.
9	
10	import { zValidator } from "@hono/zod-validator";
11	import {
12	  type CardBrief,
13	  cardBriefSchema,
14	  cardSchema,
15	  type CatalogFacets,
16	  catalogFacetsSchema,
17	  type Paginated,
18	  paginatedSchema,
19	  serieSchema,
20	  setBriefSchema,
21	  setWithCardsSchema,
22	} from "@luminous/schema";
23	import { and, asc, count, eq, inArray, isNotNull, type SQL } from "drizzle-orm";
24	import type { BatchItem } from "drizzle-orm/batch";
25	import { drizzle, type DrizzleD1Database } from "drizzle-orm/d1";
26	import { type Context, Hono } from "hono";
27	import { z } from "zod";
28	import { cards, series, sets } from "../db/schema";
29	import { chunk, D1_MAX_BOUND_PARAMS } from "../decks/validate";
30	import type { Env } from "../env";
31	import { catalogCache } from "./cache";
32	import {
33	  cardBriefColumns,
34	  type CardBriefRow,
35	  mapCardBriefRow,
36	  mapCardRow,
37	  mapSerieRow,
38	  mapSetBriefRow,
39	  mapSetRow,
40	} from "./map";
41	import {
42	  buildCardsWhere,
43	  type CardsQuery,
44	  cardsOrder,
45	  cardsQuerySchema,
46	  compareCardRows,
47	  setsQuerySchema,
48	} from "./query";
49	
50	export const catalogRoutes = new Hono<{ Bindings: Env }>();
51	
52	// Response schemas — the domain shapes each route parses itself against.
53	const cardsResponseSchema = paginatedSchema(cardBriefSchema);
54	const setsResponseSchema = z.array(setBriefSchema);
55	const seriesResponseSchema = z.array(serieSchema);
56	
57	/** Terse 400 for bad query params, e.g. `{"error":"invalid query","issues":["pageSize: …"]}`. */
58	// zValidator surfaces the zod-core error type, hence z.core.$ZodError here.
59	function invalidQuery(c: Context, error: z.core.$ZodError) {
60	  const issues = error.issues.map(
61	    (issue) => `${issue.path.map(String).join(".") || "query"}: ${issue.message}`,
62	  );
63	  return c.json({ error: "invalid query", issues }, 400);
64	}
65	
66	/** Ids per hydration statement — half the D1 cap, so each chunk's statement
67	    keeps generous headroom for the other composable filters' binds. */
68	const ID_CHUNK_SIZE = D1_MAX_BOUND_PARAMS / 2;
69	
70	/** db.batch demands a non-empty tuple (the decks routes' shape). */
71	type Batch = [BatchItem<"sqlite">, ...BatchItem<"sqlite">[]];
72	
73	/**
74	 * The id-hydration path of GET /cards (repeatable `id`): one logical
75	 * `id IN (…)` AND-ed with the regular filters. Chunked into a single
76	 * db.batch because LIMIT/OFFSET bind parameters too — a lone 100-id
77	 * statement would already brush D1's cap. The ≤ MAX_ID_VALUES matches are
78	 * then ordered and paged in memory, mirroring the SQL path's semantics
79	 * (compareCardRows is cardsOrder's JS twin).
80	 */
81	async function cardsByIds(
82	  db: DrizzleD1Database,
83	  query: CardsQuery,
84	  ids: string[],
85	  where: SQL | undefined,
86	): Promise<Paginated<CardBrief>> {
87	  const selects: BatchItem<"sqlite">[] = chunk([...new Set(ids)], ID_CHUNK_SIZE).map((group) =>
88	    db
89	      .select(cardBriefColumns)
90	      .from(cards)
91	      .where(and(where, inArray(cards.id, group))),
92	  );
93	  const rows = ((await db.batch(selects as Batch)) as CardBriefRow[][]).flat();
94	  rows.sort((a, b) => compareCardRows(query.sort, a, b));
95	  const start = (query.page - 1) * query.pageSize;
96	  return {
97	    items: rows.slice(start, start + query.pageSize).map(mapCardBriefRow),
98	    page: query.page,
99	    pageSize: query.pageSize,
100	    total: rows.length,
101	  };
102	}
103	
104	catalogRoutes.get(
105	  "/cards",
106	  catalogCache,
107	  zValidator("query", cardsQuerySchema, (result, c) =>
108	    result.success ? undefined : invalidQuery(c, result.error),
109	  ),
110	  async (c) => {
111	    const query = c.req.valid("query");
112	    const db = drizzle(c.env.DB);
113	    const where = buildCardsWhere(query);
114	    if (query.id !== undefined) {
115	      return c.json(cardsResponseSchema.parse(await cardsByIds(db, query, query.id, where)));
116	    }
117	    const [rows, totals] = await db.batch([
118	      db
119	        .select(cardBriefColumns)
120	        .from(cards)
121	        .where(where)
122	        .orderBy(...cardsOrder(query.sort))
123	        .limit(query.pageSize)
124	        .offset((query.page - 1) * query.pageSize),
125	      db.select({ total: count() }).from(cards).where(where),
126	    ]);
127	    const payload: Paginated<CardBrief> = {
128	      items: rows.map(mapCardBriefRow),
129	      page: query.page,
130	      pageSize: query.pageSize,
131	      total: totals[0]?.total ?? 0,
132	    };
133	    return c.json(cardsResponseSchema.parse(payload));
134	  },
135	);
136	
137	catalogRoutes.get("/cards/:id", catalogCache, async (c) => {
138	  const row = await drizzle(c.env.DB)
139	    .select()
140	    .from(cards)
141	    .where(eq(cards.id, c.req.param("id")))
142	    .get();
143	  if (row === undefined) {
144	    return c.json({ error: "card not found" }, 404);
145	  }
146	  return c.json(cardSchema.parse(mapCardRow(row)));
147	});
148	
149	catalogRoutes.get(
150	  "/sets",
151	  catalogCache,
152	  zValidator("query", setsQuerySchema, (result, c) =>
153	    result.success ? undefined : invalidQuery(c, result.error),
154	  ),
155	  async (c) => {
156	    const { serie } = c.req.valid("query");
157	    const rows = await drizzle(c.env.DB)
158	      .select()
159	      .from(sets)
160	      .where(serie === undefined ? undefined : eq(sets.serieId, serie))
161	      .orderBy(asc(sets.releaseDate), asc(sets.id))
162	      .all();
163	    return c.json(setsResponseSchema.parse(rows.map(mapSetBriefRow)));
164	  },
165	);
166	
167	catalogRoutes.get("/sets/:id", catalogCache, async (c) => {
168	  const setId = c.req.param("id");
169	  const db = drizzle(c.env.DB);
170	  const [setRows, cardRows] = await db.batch([
171	    db.select().from(sets).where(eq(sets.id, setId)),
172	    db
173	      .select(cardBriefColumns)
174	      .from(cards)
175	      .where(eq(cards.setId, setId))
176	      .orderBy(asc(cards.localId)),
177	  ]);
178	  const row = setRows[0];
179	  if (row === undefined) {
180	    return c.json({ error: "set not found" }, 404);
181	  }
182	  return c.json(
183	    setWithCardsSchema.parse({ ...mapSetRow(row), cards: cardRows.map(mapCardBriefRow) }),
184	  );
185	});
186	
187	catalogRoutes.get("/series", catalogCache, async (c) => {
188	  const db = drizzle(c.env.DB);
189	  // ~1 serie per era, so fetch all sets once and group in memory.
190	  const [serieRows, setRows] = await db.batch([
191	    db.select().from(series).orderBy(asc(series.releaseDate), asc(series.id)),
192	    db.select().from(sets).orderBy(asc(sets.releaseDate), asc(sets.id)),
193	  ]);
194	  const payload = serieRows.map((serieRow) =>
195	    mapSerieRow(
196	      serieRow,
197	      setRows.filter((setRow) => setRow.serieId === serieRow.id),
198	    ),
199	  );
200	  return c.json(seriesResponseSchema.parse(payload));
201	});
202	
203	/** Non-null scalar facet rows → the string list (SQL already sorted them). */
204	const facetValues = (rows: { value: string | null }[]): string[] =>
205	  rows.flatMap((row) => (row.value !== null ? [row.value] : []));
206	
207	// GET /facets — the filter vocabularies actually present in the catalog (P2
208	// task 10), feeding the web's selects instead of hardcoded constants. Seven
209	// DISTINCTs in one D1 round trip; `types` holds ARRAYS per row, so its
210	// distinct rows flatten + dedupe + sort in memory (the vocabulary is tiny).
211	catalogRoutes.get("/facets", catalogCache, async (c) => {
212	  const db = drizzle(c.env.DB);
213	  const [rarityRows, typeRows, stageRows, trainerRows, energyRows, illustratorRows, markRows] =
214	    await db.batch([
215	      db
216	        .selectDistinct({ value: cards.rarity })
217	        .from(cards)
218	        .where(isNotNull(cards.rarity))
219	        .orderBy(asc(cards.rarity)),
220	      db.selectDistinct({ value: cards.typesJson }).from(cards).where(isNotNull(cards.typesJson)),
221	      db
222	        .selectDistinct({ value: cards.stage })
223	        .from(cards)
224	        .where(isNotNull(cards.stage))
225	        .orderBy(asc(cards.stage)),
226	      db
227	        .selectDistinct({ value: cards.trainerType })
228	        .from(cards)
229	        .where(isNotNull(cards.trainerType))
230	        .orderBy(asc(cards.trainerType)),
231	      db
232	        .selectDistinct({ value: cards.energyType })
233	        .from(cards)
234	        .where(isNotNull(cards.energyType))
235	        .orderBy(asc(cards.energyType)),
236	      db
237	        .selectDistinct({ value: cards.illustrator })
238	        .from(cards)
239	        .where(isNotNull(cards.illustrator))
240	        .orderBy(asc(cards.illustrator)),
241	      db
242	        .selectDistinct({ value: cards.regulationMark })
243	        .from(cards)
244	        .where(isNotNull(cards.regulationMark))
245	        .orderBy(asc(cards.regulationMark)),
246	    ]);
247	  const payload: CatalogFacets = {
248	    rarities: facetValues(rarityRows),
249	    types: [...new Set(typeRows.flatMap((row) => row.value ?? []))].sort(),
250	    stages: facetValues(stageRows),
251	    trainerTypes: facetValues(trainerRows),
252	    energyTypes: facetValues(energyRows),
253	    illustrators: facetValues(illustratorRows),
254	    regulationMarks: facetValues(markRows),
255	  };
256	  return c.json(catalogFacetsSchema.parse(payload));
257	});
258

1	// GET /cards (and /sets) query vocabulary: zod schemas for the query strings
2	// (validated in routes.ts via @hono/zod-validator) and the Drizzle `where`
3	// builder. Pure — no Worker types — so filters unit-test as plain functions.
4	
5	import { cardCategorySchema } from "@luminous/schema";
6	import {
7	  and,
8	  type AnyColumn,
9	  asc,
10	  desc,
11	  eq,
12	  gte,
13	  inArray,
14	  lte,
15	  or,
16	  type SQL,
17	  sql,
18	} from "drizzle-orm";
19	import { z } from "zod";
20	import { cards, sets } from "../db/schema";
21	
22	/** A query-string field that must be non-empty when present. */
23	const param = z.string().min(1);
24	
25	/** A field that may repeat (`?type=Fire&type=Water`), OR-ed within its
26	    dimension. hono's query validator hands a repeated key to zod as an
27	    array and a single occurrence as a string; both normalize to a
28	    non-empty string[] here. */
29	const multiParam = z
30	  .union([param, z.array(param).min(1)])
31	  .transform((value) => (Array.isArray(value) ? value : [value]));
32	
33	/** Cap on repeatable `id` values. A deck holds ≤60 unique cards, so 100 is
34	    generous headroom for the hydration use case; excess 400s. The cap bounds
35	    the in-memory hydration path in routes.ts, which chunks the IN list under
36	    D1's bound-parameter limit (a single 100-id statement plus LIMIT/OFFSET
37	    binds would already exceed it). */
38	export const MAX_ID_VALUES = 100;
39	
40	/**
41	 * GET /cards query params. Numbers arrive as strings, hence `z.coerce`;
42	 * unknown params are ignored (zod objects strip); empty values 400.
43	 */
44	export const cardsQuerySchema = z.object({
45	  /** Exact card id(s) for batched deck hydration, e.g. "sv06.5-001"
46	      (repeatable, ≤ MAX_ID_VALUES). Composes with every other filter. */
47	  id: multiParam.pipe(z.array(param).max(MAX_ID_VALUES)).optional(),
48	  /** Case-insensitive substring of the card name. */
49	  name: param.optional(),
50	  /** Case-insensitive WHOLE-name equality — the import flow's "find this
51	      exact card" lookup, distinct from the substring `name`. */
52	  nameExact: param.optional(),
53	  category: cardCategorySchema.optional(),
54	  /** Energy type(s) the card must have one of, e.g. "Water" (repeatable). */
55	  type: multiParam.optional(),
56	  /** Exact rarity string(s), e.g. "Double rare" (repeatable). */
57	  rarity: multiParam.optional(),
58	  /** Pokémon stage(s), e.g. "Basic" (repeatable, vocabulary: GET /facets). */
59	  stage: multiParam.optional(),
60	  /** Trainer subtype(s), e.g. "Item" (repeatable, vocabulary: GET /facets). */
61	  trainerType: multiParam.optional(),
62	  /** Energy subtype(s): "Normal" / "Special" (repeatable). */
63	  energyType: multiParam.optional(),
64	  /** Set id, e.g. "sv06.5". */
65	  set: param.optional(),
66	  /** Serie id, e.g. "sv" — cards whose set belongs to the serie. */
67	  serie: param.optional(),
68	  /** Exact illustrator (vocabulary: GET /facets). */
69	  illustrator: param.optional(),
70	  /** Case-insensitive substring over ability/attack names + text. */
71	  text: param.optional(),
72	  /** Exact regulation mark, e.g. "H". */
73	  regulationMark: param.optional(),
74	  /** Inclusive HP bounds (Pokémon only — non-Pokémon have NULL hp and never match). */
75	  hpMin: z.coerce.number().int().min(0).optional(),
76	  hpMax: z.coerce.number().int().min(0).optional(),
77	  /** Keep only cards currently legal in the given format. */
78	  legal: z.enum(["standard", "expanded"]).optional(),
79	  /** Result order; "set" is collector order, the historical default. */
80	  sort: z.enum(["name", "hp-desc", "set"]).default("set"),
81	  /** 1-based page. */
82	  page: z.coerce.number().int().min(1).default(1),
83	  pageSize: z.coerce.number().int().min(1).max(100).default(50),
84	});
85	export type CardsQuery = z.infer<typeof cardsQuerySchema>;
86	
87	/** GET /sets query params. */
88	export const setsQuerySchema = z.object({
89	  /** Serie id, e.g. "sv". */
90	  serie: param.optional(),
91	});
92	export type SetsQuery = z.infer<typeof setsQuerySchema>;
93	
94	/** A user-supplied term made safe inside a LIKE pattern: `\`, `%` and `_`
95	    escaped so they match literally. Pair with {@link likeEscaped}, whose
96	    ESCAPE clause makes `\` the escape character. */
97	function escapeLike(term: string): string {
98	  return term.replace(/[\\%_]/g, "\\$&");
99	}
100	
101	/** Drizzle's `like()` plus an `ESCAPE '\'` clause — the LIKE for patterns
102	    built from user input (SQLite has no default escape character). */
103	function likeEscaped(column: AnyColumn, pattern: string): SQL {
104	  return sql`${column} like ${pattern} escape '\\'`;
105	}
106	
107	/**
108	 * The Drizzle `where` for a validated /cards query; undefined = unfiltered.
109	 *
110	 * Tradeoffs, on purpose:
111	 * - `name` uses LIKE '%…%', which in SQLite is already case-insensitive for
112	 *   ASCII. `%`/`_` in the input are escaped (with an ESCAPE '\' clause) so a
113	 *   search like "50%" matches literally instead of acting as extra wildcards.
114	 * - `type` LIKEs for the quoted value inside the raw `types_json` text
115	 *   (e.g. '%"Water"%') instead of a json_each() join. Exact enough because
116	 *   no energy type is a substring of another *quoted* type; revisit if the
117	 *   vocabulary ever grows an overlapping name.
118	 * - repeated `type` / `rarity` values OR within their dimension (a card
119	 *   matches if it has ANY selected type / rarity); dimensions still AND.
120	 * - `text` LIKEs over the raw abilities/attacks JSON blobs (names and effect
121	 *   text live inside). Imprecise on purpose — it can also brush JSON keys or
122	 *   cost values — but plenty for catalog search at ~3.7k rows. Trainer/Energy
123	 *   rules text lives in `effect`, deliberately out of scope here.
124	 * - `id` is NOT built here: the hydration path in routes.ts chunks the IN
125	 *   list itself (D1 bound-parameter cap) and ANDs it with this where.
126	 */
127	export function buildCardsWhere(query: CardsQuery): SQL | undefined {
128	  const conditions: SQL[] = [];
129	  if (query.name !== undefined) {
130	    conditions.push(likeEscaped(cards.name, `%${escapeLike(query.name)}%`));
131	  }
132	  if (query.nameExact !== undefined) {
133	    // lower() = lower() rather than a wildcard-less LIKE so `%`/`_` in the
134	    // input can't act as wildcards — exact means exact. The same ASCII-only
135	    // case folding as LIKE (SQLite semantics, both sides).
136	    conditions.push(sql`lower(${cards.name}) = lower(${query.nameExact})`);
137	  }
138	  if (query.category !== undefined) {
139	    conditions.push(eq(cards.category, query.category));
140	  }
141	  if (query.type !== undefined) {
142	    const anyType = or(
143	      ...query.type.map((t) => likeEscaped(cards.typesJson, `%"${escapeLike(t)}"%`)),
144	    );
145	    if (anyType !== undefined) conditions.push(anyType);
146	  }
147	  if (query.rarity !== undefined) {
148	    conditions.push(inArray(cards.rarity, query.rarity));
149	  }
150	  if (query.stage !== undefined) {
151	    conditions.push(inArray(cards.stage, query.stage));
152	  }
153	  if (query.trainerType !== undefined) {
154	    conditions.push(inArray(cards.trainerType, query.trainerType));
155	  }
156	  if (query.energyType !== undefined) {
157	    conditions.push(inArray(cards.energyType, query.energyType));
158	  }
159	  if (query.set !== undefined) {
160	    conditions.push(eq(cards.setId, query.set));
161	  }
162	  if (query.serie !== undefined) {
163	    // Membership subquery instead of a join so the where stays composable
164	    // with the page + count pair in routes.ts; a serie holds few sets.
165	    conditions.push(
166	      sql`${cards.setId} in (select ${sets.id} from ${sets} where ${sets.serieId} = ${query.serie})`,
167	    );
168	  }
169	  if (query.illustrator !== undefined) {
170	    conditions.push(eq(cards.illustrator, query.illustrator));
171	  }
172	  if (query.text !== undefined) {
173	    const pattern = `%${escapeLike(query.text)}%`;
174	    const anyText = or(
175	      likeEscaped(cards.abilitiesJson, pattern),
176	      likeEscaped(cards.attacksJson, pattern),
177	    );
178	    if (anyText !== undefined) conditions.push(anyText);
179	  }
180	  if (query.regulationMark !== undefined) {
181	    conditions.push(eq(cards.regulationMark, query.regulationMark));
182	  }
183	  if (query.hpMin !== undefined) {
184	    conditions.push(gte(cards.hp, query.hpMin));
185	  }
186	  if (query.hpMax !== undefined) {
187	    conditions.push(lte(cards.hp, query.hpMax));
188	  }
189	  if (query.legal === "standard") {
190	    conditions.push(eq(cards.legalStandard, true));
191	  } else if (query.legal === "expanded") {
192	    conditions.push(eq(cards.legalExpanded, true));
193	  }
194	  return and(...conditions);
195	}
196	
197	/**
198	 * Deterministic collector order: (set_id, local_id), both text. Good enough
199	 * on purpose — SV-era local ids are zero-padded ("001"), so the
200	 * lexicographic sort matches collector order; a release-date join can
201	 * replace set_id if cross-set chronology ever matters (docs §6).
202	 */
203	const collectorOrder = [asc(cards.setId), asc(cards.localId)];
204	
205	/**
206	 * The ORDER BY for a validated /cards query. Every sort ends on collector
207	 * order so pages stay deterministic across equal keys. `hp-desc` relies on
208	 * SQLite treating NULL as smaller than every value — `hp DESC` puts the
209	 * hp-less Trainers/Energy last (verified against SQLite directly).
210	 */
211	export function cardsOrder(sort: CardsQuery["sort"]): SQL[] {
212	  if (sort === "name") return [asc(cards.name), ...collectorOrder];
213	  if (sort === "hp-desc") return [desc(cards.hp), ...collectorOrder];
214	  return collectorOrder;
215	}
216	
217	/** The row fields the in-memory comparator reads — the id-hydration path
218	    sorts its ≤ MAX_ID_VALUES rows in JS instead of paging in SQL. */
219	export type CardOrderFields = {
220	  name: string;
221	  hp: number | null;
222	  setId: string;
223	  localId: string;
224	};
225	
226	/**
227	 * JS twin of `cardsOrder` for the id-hydration path: same keys, same
228	 * directions, same NULL-hp-last rule, so both /cards paths page identically.
229	 * `<` on JS strings (UTF-16 code units) matches SQLite's BINARY collation
230	 * (UTF-8 bytes) for all BMP text — code-point order either way — which
231	 * covers every card name and id in the catalog.
232	 */
233	export function compareCardRows(
234	  sort: CardsQuery["sort"],
235	  a: CardOrderFields,
236	  b: CardOrderFields,
237	): number {
238	  if (sort === "name" && a.name !== b.name) {
239	    return a.name < b.name ? -1 : 1;
240	  }
241	  if (sort === "hp-desc" && a.hp !== b.hp) {
242	    if (a.hp === null) return 1;
243	    if (b.hp === null) return -1;
244	    return b.hp - a.hp;
245	  }
246	  if (a.setId !== b.setId) {
247	    return a.setId < b.setId ? -1 : 1;
248	  }
249	  if (a.localId !== b.localId) {
250	    return a.localId < b.localId ? -1 : 1;
251	  }
252	  return 0;
253	}
254

1	import { useState } from "react";
2	
3	const CARD_ASPECT_RATIO = 3.5 / 2.5;
4	
5	interface CardImageProps {
6	  imageUrl?: string;
7	  alt: string;
8	  priority?: boolean;
9	  className?: string;
10	  /** Fixed-size mode (the playmat): renders explicit width/height attributes so
11	      layout never shifts as art loads. Provide this OR set `fill`. */
12	  renderedWidth?: number;
13	  /** Fluid mode (the deck builder grid): the parent owns the box (e.g. an
14	      aspect-ratio container) and the image fills it. `className` should carry the
15	      object-fit + size utilities. */
16	  fill?: boolean;
17	}
18	
19	/** A card image with a graceful fallback: when there's no source, or the remote
20	    art 404s / fails CORS, it renders a neutral correctly-shaped tile instead of
21	    the browser's broken-image glyph. Works in two layouts — fixed (px width) for
22	    the simulator, or `fill` for a responsive grid cell. */
23	export function CardImage({
24	  imageUrl,
25	  renderedWidth,
26	  alt,
27	  priority = false,
28	  className,
29	  fill = false,
30	}: CardImageProps) {
31	  const loading = priority ? "eager" : "lazy";
32	  const fetchPriority = priority ? "high" : "auto";
33	  // Track the URL that failed (not just a boolean) so a later prop change to a
34	  // different imageUrl re-attempts the load instead of staying on the fallback.
35	  const [failedUrl, setFailedUrl] = useState<string | null>(null);
36	
37	  // Fixed mode sizes the element itself; fluid mode leaves sizing to the parent.
38	  const sized =
39	    !fill && renderedWidth !== undefined
40	      ? { width: Math.round(renderedWidth), height: Math.round(renderedWidth * CARD_ASPECT_RATIO) }
41	      : undefined;
42	
43	  if (!imageUrl || failedUrl === imageUrl) {
44	    return (
45	      <div
46	        className={className}
47	        style={{ ...(sized ?? {}), background: "#161621" }}
48	        aria-label={alt}
49	        role="img"
50	      />
51	    );
52	  }
53	
54	  return (
55	    <img
56	      src={imageUrl}
57	      alt={alt}
58	      width={sized?.width}
59	      height={sized?.height}
60	      loading={loading}
61	      decoding="async"
62	      fetchPriority={fetchPriority}
63	      referrerPolicy="no-referrer"
64	      className={className}
65	      style={{ imageRendering: "auto", display: "block" }}
66	      draggable={false}
67	      onError={() => setFailedUrl(imageUrl)}
68	    />
69	  );
70	}
