1	import type { PointerEvent as ReactPointerEvent, ReactNode } from "react";
2	import { CardImage } from "../../../components/CardImage";
3	import { AlertTriangleIcon, DecksIcon } from "../../../components/icons";
4	import { useTiltJuice } from "../../../components/useTiltJuice";
5	import { cardImageUrl } from "../../../lib/api";
6	import { FOCUS_RING_INSET, GLASS_GHOST_BUTTON } from "../../../lib/glass";
7	import type { BuilderCard } from "../cards";
8	
9	// The pile cards peek out only their bottom edge, so — like the decks page's
10	// deck stacks — they're a flat "card-edge" blue matching the card back's inner
11	// border rather than the (darker-at-the-bottom) full back image.
12	const CARD_EDGE = "#28345a";
13	
14	export interface CardGridProps {
15	  /** The tiles to show — the loaded pages AFTER the client-side kind filter. */
16	  cards: BuilderCard[];
17	  /** How many cards the loaded pages hold BEFORE the kind filter — pairs with
18	      `total` for the "n of m loaded" caption. */
19	  loadedCount: number;
20	  /** Server-side match count, or null until the first page lands. */
21	  total: number | null;
22	  /** The first page is in flight (previous results keep showing meanwhile). */
23	  loading: boolean;
24	  /** A later page is in flight. */
25	  loadingMore: boolean;
26	  /** "initial" = nothing to show; "more" = the loaded pages still stand. */
27	  error: "initial" | "more" | null;
28	  hasMore: boolean;
29	  onLoadMore: () => void;
30	  onRetry: () => void;
31	  /** Copies of a card currently in the deck. */
32	  countOf: (card: BuilderCard) => number;
33	  /** Copies still addable (0 = at the per-name cap). */
34	  remainingOf: (card: BuilderCard) => number;
35	  onAdd: (card: BuilderCard) => void;
36	  onRemove: (card: BuilderCard) => void;
37	  /** Suppress the pointer tilt while any drag is in flight. */
38	  dragActive?: boolean;
39	  /** Begin a drag of this card (to drop on the deck). */
40	  onDragStart?: (card: BuilderCard, event: ReactPointerEvent<HTMLElement>) => void;
41	  /** When this points at a card id with a new nonce, that tile shakes. */
42	  pulse?: { cardId: string; n: number } | null;
43	}
44	
45	type TileHandlers = Pick<
46	  CardGridProps,
47	  "countOf" | "remainingOf" | "onAdd" | "onRemove" | "dragActive" | "onDragStart" | "pulse"
48	>;
49	
50	function CardTile({
51	  card,
52	  countOf,
53	  remainingOf,
54	  onAdd,
55	  onRemove,
56	  dragActive,
57	  onDragStart,
58	  pulse,
59	}: { card: BuilderCard } & TileHandlers) {
60	  const count = countOf(card);
61	  const inDeck = count > 0;
62	  const remaining = remainingOf(card);
63	  const maxed = remaining <= 0;
64	  // The gallery shows each card's remaining supply: a full pile of four behind
65	  // the top card by default, thinning as copies are drafted into the deck.
66	  const pile = Math.min(remaining, 4);
67	  // Balatro tilt + press juice on the top card, like the decks-page tiles.
68	  // Suppressed while a drag is in flight, and on maxed cards (which can't take
69	  // another copy, so they're not interactive).
70	  const { tiltRef, juiceLayerRef, juiceStyle, tiltStyle, handlers } =
71	    useTiltJuice<HTMLButtonElement>({
72	      disabled: dragActive || maxed,
73	      pulse: pulse && pulse.cardId === card.cardId ? pulse.n : null,
74	    });
75	
76	  return (
77	    <li className="relative transition-[z-index] hover:z-10">
78	      {/* Pile — the copies still available to add, peeking out the bottom as
79	          card-back edges. */}
80	      {Array.from({ length: pile }, (_, i) => (
81	        <div
82	          key={i}
83	          aria-hidden
84	          style={{ transform: `translateY(${(pile - i) * 4}px)`, backgroundColor: CARD_EDGE }}
85	          className="absolute inset-0 rounded-xl shadow-[0_2px_6px_rgba(0,0,0,0.35)]"
86	        />
87	      ))}
88	      {/* Outer layer carries the squash/wobble juice; the button beneath it
89	          carries the pointer tilt and is the full-cover add target. Click adds a
90	          copy; right-click removes one (the browser menu is suppressed). */}
91	      <div ref={juiceLayerRef} style={juiceStyle}>
92	        <button
93	          ref={tiltRef}
94	          type="button"
95	          {...handlers}
96	          // No press juice here: the copy-count `pulse` already shakes this tile
97	          // when the click adds a copy, so firing on pointerDown too would
98	          // double-shake (a press bounce on mouse-down, then the pulse on mouse-up).
99	          onPointerDown={(e) => {
100	            if (!maxed) onDragStart?.(card, e);
101	          }}
102	          style={tiltStyle}
103	          aria-label={
104	            maxed
105	              ? `${card.name}, maximum copies reached`
106	              : inDeck
107	                ? `Add ${card.name}, ${count} in deck`
108	                : `Add ${card.name}`
109	          }
110	          onClick={() => onAdd(card)}
111	          onContextMenu={(e) => {
112	            e.preventDefault();
113	            if (inDeck) onRemove(card);
114	          }}
115	          className={`relative block w-full cursor-pointer overflow-hidden rounded-xl ring-inset ${FOCUS_RING_INSET} ${
116	            maxed ? "cursor-not-allowed" : inDeck ? "ring-1 ring-accent/70" : "ring-1 ring-white/10"
117	          }`}
118	        >
119	          <div className={`aspect-[2.5/3.5] w-full ${maxed ? "opacity-45 saturate-[0.7]" : ""}`}>
120	            {/* Grid tiles are thumbnails — the "low" scan; no URL at all when
121	                the catalog has no scan, so the fallback tile shows instead of
122	                a request that would 404. */}
123	            <CardImage
124	              fill
125	              imageUrl={card.hasImage ? cardImageUrl(card.cardId, "low") : undefined}
126	              alt={card.name}
127	              className="h-full w-full object-cover"
128	            />
129	          </div>
130	        </button>
131	      </div>
132	    </li>
133	  );
134	}
