136	/** Centred placeholder for the grid's empty-ish states — the same visual
137	    language as the decks page's empty library. */
138	function GridNotice({
139	  icon,
140	  children,
141	  action,
142	}: {
143	  icon: ReactNode;
144	  children: ReactNode;
145	  action?: ReactNode;
146	}) {
147	  return (
148	    <div className="flex flex-col items-center justify-center gap-3 px-6 pb-16 pt-32 text-center">
149	      {icon}
150	      <p className="text-sm font-medium text-white/55">{children}</p>
151	      {action}
152	    </div>
153	  );
154	}
