156	/** The centre pane's card grid over the paginated catalog search. Column
157	    counts mirror the decks library grid so a card here renders at the same
158	    size as a deck tile there (same width column, same aspect). Each tile is a
159	    static card face; available copies stack up as a pile behind it (the wider
160	    row gap leaves room for that pile to peek out). Below the tiles: the
161	    "load more" footer for the next server page. */
162	export function CardGrid({
163	  cards,
164	  loadedCount,
165	  total,
166	  loading,
167	  loadingMore,
168	  error,
169	  hasMore,
170	  onLoadMore,
171	  onRetry,
172	  ...handlers
173	}: CardGridProps) {
174	  if (error === "initial") {
175	    return (
176	      <GridNotice
177	        icon={<AlertTriangleIcon className="h-6 w-6 text-white/20" />}
178	        action={
179	          <button
180	            type="button"
181	            onClick={onRetry}
182	            className={`rounded-full px-3.5 py-1.5 text-sm font-medium ${GLASS_GHOST_BUTTON}`}
183	          >
184	            Retry
185	          </button>
186	        }
187	      >
188	        Couldn't load the card catalog
189	      </GridNotice>
190	    );
191	  }
192	
193	  if (cards.length === 0 && loading) {
194	    return (
195	      <GridNotice icon={<DecksIcon className="h-6 w-6 animate-pulse text-white/20" />}>
196	        Loading cards…
197	      </GridNotice>
198	    );
199	  }
200	
201	  if (cards.length === 0 && !hasMore && error === null) {
202	    return (
203	      <GridNotice icon={<DecksIcon className="h-6 w-6 text-white/20" />}>
204	        No cards match these filters
205	      </GridNotice>
206	    );
207	  }
208	
209	  return (
210	    <>
211	      {cards.length > 0 ? (
212	        <ul className="grid grid-cols-2 gap-x-3 gap-y-6 pt-4 md:grid-cols-3 lg:grid-cols-5">
213	          {cards.map((card) => (
214	            <CardTile key={card.cardId} card={card} {...handlers} />
215	          ))}
216	        </ul>
217	      ) : (
218	        // The client-side kind filter hid everything the loaded pages held,
219	        // but the server has more — offer the next page, not a dead end.
220	        <GridNotice icon={<DecksIcon className="h-6 w-6 text-white/20" />}>
221	          No matching cards loaded yet
222	        </GridNotice>
223	      )}
224	      {(hasMore || error === "more") && (
225	        <div className="flex flex-col items-center gap-2 pb-6 pt-6">
226	          {error === "more" && (
227	            <p className="text-xs font-medium text-amber-200/80">Couldn't load more cards</p>
228	          )}
229	          <button
230	            type="button"
231	            onClick={error === "more" ? onRetry : onLoadMore}
232	            disabled={loadingMore}
233	            className={`rounded-full px-4 py-2 text-sm font-medium disabled:cursor-default disabled:opacity-60 ${GLASS_GHOST_BUTTON}`}
234	          >
235	            {loadingMore ? "Loading…" : error === "more" ? "Retry" : "Load more"}
236	          </button>
237	          {total !== null && (
238	            <p className="text-xs tabular-nums text-white/40">
239	              {loadedCount} of {total} loaded
240	            </p>
241	          )}
242	        </div>
243	      )}
244	    </>
245	  );
246	}
