1	// Card model + metadata for the deck builder. The card *data* comes from the
2	// live catalog api (fetched by useCardSearch, adapted in catalog.ts); this
3	// module holds the types, the energy-type palette, the format definitions,
4	// and small pure helpers shared across the builder. Kept pixi-free and
5	// side-effect-free so the pure logic (deckMath, decklistText) and their
6	// tests can import it freely.
7	
8	import { BASIC_ENERGY_TYPES, type BasicEnergyType } from "@luminous/schema";
9	import { ENERGY_COLORS } from "../../lib/energyPalette";
10	
11	/** The energy types the builder filters and paints, in the canonical wheel
12	    order. Derived from the shared basic-energy vocabulary (@luminous/schema)
13	    minus the retired Fairy — old Fairy prints keep adapting to typeless
14	    tiles rather than growing a palette entry — plus Dragon (a Pokémon type
15	    with no Basic Energy) and Colorless (a cost symbol), which exist only in
16	    this UI palette. */
17	export type EnergyType = Exclude<BasicEnergyType, "Fairy"> | "Dragon" | "Colorless";
18	
19	export const ENERGY_TYPES: readonly EnergyType[] = [
20	  ...BASIC_ENERGY_TYPES.filter(
21	    (type): type is Exclude<BasicEnergyType, "Fairy"> => type !== "Fairy",
22	  ),
23	  "Dragon",
24	  "Colorless",
25	];
26	
27	/** Top-level card category — drives the deck-list grouping (Pokémon / Trainer /
28	    Energy) and the right-panel split. Uses the accented "Pokémon" spelling the
29	    game itself uses. */
30	export type Supertype = "Pokémon" | "Trainer" | "Energy";
31	
32	export const SUPERTYPES: Supertype[] = ["Pokémon", "Trainer", "Energy"];
33	
34	// NOTE (P2 task 10): the printed-subtype and rarity vocabularies used to be
35	// hardcoded tuples here (POKEMON_STAGES, TRAINER_SUBTYPES, RARITIES, …). They
36	// now come from the live catalog — GET /facets via useCatalogOptions — so a
37	// card's `subtype` and `rarity` stay plain strings and the rail's chips
38	// reflect what is actually ingested.
39	
40	/** A single browsable card — the builder's view of a catalog card (adapted
41	    from the api shapes in catalog.ts). `cardId` is the tcgdex id ("sv06.5-001"),
42	    also the key of the api's art mirror. Optional fields are absent for
43	    categories they don't apply to (a Trainer has no `types`/`hp`, an Energy
44	    no `hp`, etc.). */
45	export interface BuilderCard {
46	  cardId: string;
47	  name: string;
48	  supertype: Supertype;
49	  /** Basic | Stage 1 | Stage 2 | Item | Supporter | Stadium | Pokémon Tool |
50	      Basic Energy | Special Energy — or a newer printed subtype the catalog
51	      knows and this build's tuples don't. */
52	  subtype: string;
53	  /** Energy type(s) — Pokémon (its type) and most Energy cards. */
54	  types?: EnergyType[];
55	  hp?: number;
56	  /** Regulation mark (e.g. "H", "I"), the basis of Standard-format legality. */
57	  regulationMark?: string;
58	  /** Exact catalog rarity string, e.g. "Double rare". */
59	  rarity?: string;
60	  /** Collector number within its set (the catalog's localId, e.g. "081"). */
61	  number?: string;
62	  /** Whether the catalog has a scan for this card — when false, tiles render
63	      the neutral fallback instead of requesting art that would 404. */
64	  hasImage?: boolean;
65	  /** The catalog's structured format-legality verdict (P2) — present on every
66	      api-adapted card; optional only for hand-built fixtures. Groundwork for
67	      validateDeck to stop inferring legality from regulation marks. */
68	  legal?: { standard: boolean; expanded: boolean };
69	}
70	
71	/** True for a Basic Pokémon — the card a legal deck must contain at least one
72	    of, and the only Pokémon that can start play. */
73	export function isBasicPokemon(card: BuilderCard): boolean {
74	  return card.supertype === "Pokémon" && card.subtype === "Basic";
75	}
76	
77	/** True for a basic Energy — the lone exception to the 4-copies-per-name rule. */
78	export function isBasicEnergy(card: BuilderCard): boolean {
79	  return card.supertype === "Energy" && card.subtype === "Basic Energy";
80	}
81	
82	/** The most copies of any one ACE SPEC card — and of all ACE SPECs combined —
83	    a deck may hold. */
84	export const ACE_SPEC_LIMIT = 1;
85	
86	/** True for an ACE SPEC card. A deck may contain only one ACE SPEC in total
87	    (across every name), enforced in {@link validateDeck}. Identified by rarity,
88	    which is how the printed cards mark themselves — the catalog's exact string
89	    is "ACE SPEC Rare" (verified against the live facets vocabulary); the
90	    substring match keeps older fixture spellings working too. */
91	export function isAceSpec(card: BuilderCard): boolean {
92	  return (card.rarity ?? "").includes("ACE SPEC");
93	}
94	
95	// Radiant and Prism Star are NAME-defined card classes — the game names every
96	// member "Radiant X" / "X ◇" and hangs the deck rule off that name — so a name
97	// check IS the structured detection, not a stand-in for missing data.
98	
99	/** The most Radiant Pokémon — across every name — a deck may hold. */
100	export const RADIANT_LIMIT = 1;
101	
102	/** True for a Radiant Pokémon ("Radiant Greninja", …) — like ACE SPEC, a deck
103	    may contain only one Radiant Pokémon in total, across every name
104	    ({@link validateDeck}). */
105	export function isRadiantPokemon(card: BuilderCard): boolean {
106	  return card.supertype === "Pokémon" && card.name.startsWith("Radiant ");
107	}
108	
109	/** True for a Prism Star card — tcgdex prints the "◇" suffix in the name
110	    ("Diancie ◇"); the spelled-out form covers other decklist sources. Limited
111	    to one copy of a given name per deck ({@link validateDeck}). */
112	export function isPrismStar(card: BuilderCard): boolean {
113	  return card.name.includes("◇") || card.name.endsWith(" Prism Star");
114	}
115	
116	/** Whether a card is legal in a format. The catalog's structured verdict
117	    (`card.legal`, keyed by the format's {@link Format.legalFlag}) is the
118	    source of truth — every api-sourced card carries it. Cards without it
119	    (hand-built fixtures, pre-P2 data) degrade to the printed regulation-mark
120	    check: formats with no `legalRegulationMarks` impose no mark cutoff, and
121	    an unmarked card (basic Energy) is always legal. */
122	export function isLegalInFormat(card: BuilderCard, format: Format): boolean {
123	  if (format.legalFlag === undefined) return true;
124	  if (card.legal) return card.legal[format.legalFlag];
125	  if (!format.legalRegulationMarks) return true;
126	  if (!card.regulationMark) return true;
127	  return format.legalRegulationMarks.includes(card.regulationMark);
128	}
129	
130	// --- Card kinds --------------------------------------------------------------
131	// The rail's contextual filter offers card "kinds" once a supertype is chosen.
132	// Printed kinds (stages / trainer subtypes / energy subtypes) come from the
133	// catalog's facets and filter SERVER-side (catalog.filtersToCardsQuery maps
134	// them to the stage/trainerType/energyType params). Only the DERIVED kinds
135	// below stay client-side: they're read off the card NAME because tcgdex's
136	// `suffix` field isn't persisted — there is no structured column to query.
137	
138	export interface DerivedKind {
139	  label: string;
140	  match: (card: BuilderCard) => boolean;
141	}
142	
143	export const DERIVED_KINDS: DerivedKind[] = [
144	  { label: "EX", match: (c) => /\bex\b/i.test(c.name) },
145	  { label: "Mega", match: (c) => /\bmega\b/i.test(c.name) },
146	];
147	
148	/** True for a kind label the server can't express (name-regex kinds). */
149	export function isDerivedKind(label: string): boolean {
150	  return DERIVED_KINDS.some((kind) => kind.label === label);
151	}
152	
153	/** OR within the card-kind dimension: derived kinds match by name regex,
154	    printed kinds by subtype equality (builder labels — "Stage 1", "Pokémon
155	    Tool", …). Only consulted when a derived kind is selected; otherwise the
156	    whole dimension filtered server-side (poolFilter.filterVisibleCards). */
157	export function cardMatchesKinds(card: BuilderCard, labels: string[]): boolean {
158	  return labels.some((label) => {
159	    const derived = DERIVED_KINDS.find((kind) => kind.label === label);
160	    return derived ? derived.match(card) : card.subtype === label;
161	  });
162	}
163	
164	// --- Energy-type palette ---------------------------------------------------
165	// One accent per type for the pips on Pokémon tiles and the type-distribution
166	// bar in the deck stats. The hex values live in the shared app-wide palette
167	// (src/lib/energyPalette.ts — also behind the game HUD's cost dots) so the
168	// colors can't drift between features; the one-letter `code` is the game's
169	// own energy abbreviation (Grass G, Fire R, Water W, …).
170	
171	export interface EnergyTypeMeta {
172	  type: EnergyType;
173	  /** Single-letter energy abbreviation used on compact chips. */
174	  code: string;
175	  /** Accent colour (hex) for pips and the distribution bar. */
176	  color: string;
177	}
178	
179	export const ENERGY_TYPE_META: Record<EnergyType, EnergyTypeMeta> = {
180	  Grass: { type: "Grass", code: "G", color: ENERGY_COLORS.Grass },
181	  Fire: { type: "Fire", code: "R", color: ENERGY_COLORS.Fire },
182	  Water: { type: "Water", code: "W", color: ENERGY_COLORS.Water },
183	  Lightning: { type: "Lightning", code: "L", color: ENERGY_COLORS.Lightning },
184	  Psychic: { type: "Psychic", code: "P", color: ENERGY_COLORS.Psychic },
185	  Fighting: { type: "Fighting", code: "F", color: ENERGY_COLORS.Fighting },
186	  Darkness: { type: "Darkness", code: "D", color: ENERGY_COLORS.Darkness },
187	  Metal: { type: "Metal", code: "M", color: ENERGY_COLORS.Metal },
188	  Dragon: { type: "Dragon", code: "N", color: ENERGY_COLORS.Dragon },
189	  Colorless: { type: "Colorless", code: "C", color: ENERGY_COLORS.Colorless },
190	};
191	
192	// --- Formats ---------------------------------------------------------------
193	
194	export interface Format {
195	  id: string;
196	  name: string;
197	  /** Required deck size (constructed Pokémon TCG is 60). */
198	  deckSize: number;
199	  /** Max copies of any one card by name (basic Energy is always exempt). */
200	  maxCopiesByName: number;
201	  /** Minimum Basic Pokémon a legal deck must contain. */
202	  minBasicPokemon: number;
203	  /** The card-legality flag this format reads — the key into the catalog's
204	      structured `card.legal` verdict, and the value of GET /cards' `legal`
205	      param. Undefined = an unrestricted format (none modelled today). One
206	      field feeds both the validator and the rail's legal-only filter, so the
207	      two can't disagree (the P2 task 13 unification). */
208	  legalFlag?: "standard" | "expanded";
209	  /** Regulation marks legal in this format; undefined = no mark restriction.
210	      FALLBACK ONLY — consulted for cards without the structured `legal` block
211	      (hand-built fixtures); api-sourced cards always carry the verdict. */
212	  legalRegulationMarks?: string[];
213	  description: string;
214	}
215	
216	// Standard's legal regulation marks rotate each year; the set here is filled
217	// from the rules research and is easy to bump when the next rotation lands.
218	// Named (not FORMATS[0]) so DEFAULT_FORMAT is statically known to exist — under
219	// noUncheckedIndexedAccess an index access would widen to `Format | undefined`
220	// and ripple through everything that reads the default.
221	const STANDARD_FORMAT: Format = {
222	  id: "standard",
223	  name: "Standard",
224	  deckSize: 60,
225	  maxCopiesByName: 4,
226	  minBasicPokemon: 1,
227	  legalFlag: "standard",
228	  // Mark-check fallback for cards without `legal`: the marks after the April
229	  // 2026 rotation (G rotated out); bump this list when the next rotation lands.
230	  legalRegulationMarks: ["H", "I", "J"],
231	  description: "Most recent sets — the default tournament format.",
232	};
233	
234	export const FORMATS: Format[] = [
235	  STANDARD_FORMAT,
236	  {
237	    id: "expanded",
238	    name: "Expanded",
239	    deckSize: 60,
240	    maxCopiesByName: 4,
241	    minBasicPokemon: 1,
242	    // Structured legality only — no mark fallback (Expanded spans far more
243	    // sets than the mark system covers), so a card without `legal` passes.
244	    legalFlag: "expanded",
245	    description: "Black & White onward — a far wider card pool.",
246	  },
247	];
248	
249	export const DEFAULT_FORMAT = STANDARD_FORMAT;
250	
251	export function formatById(id: string): Format {
252	  return FORMATS.find((f) => f.id === id) ?? DEFAULT_FORMAT;
253	}
