66	// ---- Session recovery (the ONE owner of 401 → re-probe → retry-once) --------
67	// A mid-session 401 usually means the cookie expired, but it can also be a
68	// one-off (a session rotated in another tab, a hiccup). Instead of every
69	// feature hand-rolling "on 401, refresh() the auth context", the client owns
70	// it: an unexpected 401 asks the installed handler to re-probe the session,
71	// and if the session turns out to still be alive the failed request is
72	// retried once. When the probe lands on signed-out, the handler's own state
73	// change (AuthProvider → "anonymous") flips the UI; the 401 then propagates
74	// to the caller as before.
75	
76	/** Re-probe the session; resolve true when it's still alive (retry the
77	    request), false when the user is really signed out. */
78	type SessionRecoveryHandler = () => Promise<boolean>;
79	
80	let recoverSession: SessionRecoveryHandler | null = null;
81	/** In-flight probe, shared so a burst of parallel 401s asks once. */
82	let recovery: Promise<boolean> | null = null;
83	
84	/** Installed by AuthProvider (null on teardown). One owner at a time. */
85	export function setSessionRecoveryHandler(handler: SessionRecoveryHandler | null): void {
86	  recoverSession = handler;
87	}
88	
89	function attemptRecovery(): Promise<boolean> {
90	  const handler = recoverSession;
91	  if (handler === null) return Promise.resolve(false);
92	  recovery ??= handler().then(
93	    (alive) => {
94	      recovery = null;
95	      return alive;
96	    },
97	    () => {
98	      recovery = null;
99	      return false;
100	    },
101	  );
102	  return recovery;
103	}
