105	/** The one fetch wrapper every call goes through: cookie on every request,
106	    JSON in/out, non-2xx → ApiError, 204 → undefined. A 401 anywhere but
107	    /auth/* runs the session-recovery hook above and retries once — /auth is
108	    excluded because there a 401 IS the answer (me() = signed out, login =
109	    wrong credentials), and because the recovery probe itself is /auth/me. */
110	async function request<T>(path: string, init?: { method?: string; body?: unknown }): Promise<T> {
111	  let response = await send(path, init);
112	  if (response.status === 401 && !path.startsWith("/auth/") && (await attemptRecovery())) {
113	    response = await send(path, init);
114	  }
115	  if (!response.ok) throw new ApiError(response.status, await errorBody(response));
116	  if (response.status === 204) return undefined as T;
117	  return (await response.json()) as T;
118	}
119	
120	function send(path: string, init?: { method?: string; body?: unknown }): Promise<Response> {
121	  const hasBody = init?.body !== undefined;
122	  return fetch(apiUrl(path), {
123	    method: init?.method ?? "GET",
124	    credentials: "include",
125	    headers: hasBody ? { "content-type": "application/json" } : undefined,
126	    body: hasBody ? JSON.stringify(init?.body) : undefined,
127	  });
128	}
129	
130	/** The parsed error payload, or undefined when it isn't JSON (proxies and
131	    the runtime itself can answer with plain-text error pages). */
132	async function errorBody(response: Response): Promise<unknown> {
133	  if (!response.headers.get("content-type")?.includes("application/json")) return undefined;
134	  try {
135	    return await response.json();
136	  } catch {
137	    return undefined;
138	  }
139	}
