141	/** `?key=value…` from the defined, non-empty params — or "" when none
142	    survive, so an unfiltered call hits the bare path. An array value emits
143	    one occurrence per non-empty item (`?type=Fire&type=Water`) — the api's
144	    repeatable-param convention; an empty array is omitted entirely. */
145	function queryString(params: Record<string, string | number | string[] | undefined>): string {
146	  const search = new URLSearchParams();
147	  for (const [key, value] of Object.entries(params)) {
148	    if (value === undefined || value === "") continue;
149	    if (Array.isArray(value)) {
150	      for (const item of value) {
151	        if (item !== "") search.append(key, item);
152	      }
153	    } else {
154	      search.append(key, String(value));
155	    }
156	  }
157	  const encoded = search.toString();
158	  return encoded === "" ? "" : `?${encoded}`;
159	}
