import { useEffect, useId, useRef } from "react";
import { CardImage } from "../../../components/CardImage";
import { CheckIcon, ImageIcon, XIcon } from "../../../components/icons";
import { ScrollArea } from "../../../components/ScrollArea";
import { cardImageUrl } from "../../../lib/api";
import {
  FOCUS_RING_INSET,
  GLASS_DIALOG_GHOST_BUTTON,
  GLASS_DIALOG_PANEL,
} from "../../../lib/glass";
import type { Deck } from "../deckMath";

// Which card fronts this deck in the library (P5-6 — the follow-up P5-3 left
// room for). The derived default is a heuristic ("the biggest Pokémon") and will
// sometimes pick the wall over the attacker beside it; here the owner overrules
// it, which is the only answer that is always right.
//
// AUTOMATIC IS AN EXPLICIT OPTION, not the absence of a choice, so going back to
// it is one click rather than a thing you cannot express. It leads the grid, and
// deliberately shows no card art: the default is a RULE, and drawing today's
// answer to it would read as "this card", which is exactly what it isn't.
//
// Picking applies immediately — like every other edit in this editor, it rides
// the debounced save — so the dialog needs no Save button, only a way out.

export interface CoverDialogProps {
  open: boolean;
  /** The deck's HYDRATED entries — the cards there is art to choose from. */
  deck: Deck;
  /** The owner's current pick, or null for the derived default. */
  chosenCoverCardId: string | null;
  /** Pin a card id, or null to go back to automatic. */
  onChoose: (cardId: string | null) => void;
  onClose: () => void;
}

const TILE_BASE =
  "relative block w-full overflow-hidden rounded-lg ring-1 ring-inset transition-all hover:scale-[1.03] active:scale-95";

export function CoverDialog({
  open,
  deck,
  chosenCoverCardId,
  onChoose,
  onClose,
}: CoverDialogProps) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const titleId = useId();

  // Native <dialog> driven by `open`, exactly like ImportExportDialog: focus
  // move-in, focus trapping, Escape and focus restoration for free.
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    if (open && !dialog.open) dialog.showModal();
    else if (!open && dialog.open) dialog.close();
  }, [open]);

  // Only cards the catalog can draw: a cover with no scan is a blank rectangle,
  // and the server resolves such a pin back to the default anyway.
  const choices = deck.filter(({ card }) => card.hasImage);

  return (
    // biome-ignore lint/a11y/useKeyWithClickEvents: the native <dialog> handles Escape; this onClick only adds backdrop click-to-dismiss for pointer users.
    <dialog
      ref={dialogRef}
      aria-labelledby={titleId}
      onClose={onClose}
      onClick={(e) => {
        // A click whose target is the dialog itself landed on the ::backdrop.
        if (e.target === dialogRef.current) onClose();
      }}
      className="m-auto border-0 bg-transparent p-0 text-white [&::backdrop]:bg-black/60 [&::backdrop]:backdrop-blur-sm"
    >
      <div className={`w-[min(34rem,calc(100vw-2rem))] ${GLASS_DIALOG_PANEL}`}>
        <div className="mb-1 flex items-center justify-between">
          <h2 id={titleId} className="text-base font-semibold text-white/90">
            Deck cover
          </h2>
          <button
            type="button"
            aria-label="Close"
            onClick={onClose}
            className={`flex h-8 w-8 cursor-pointer items-center justify-center rounded-full text-white/55 transition-colors hover:bg-white/10 hover:text-white ${FOCUS_RING_INSET}`}
          >
            <XIcon className="h-4 w-4" />
          </button>
        </div>

        <p className="mb-3 text-xs text-white/55">
          The card that fronts this deck in your library.
        </p>

        <ScrollArea className="-mx-1 max-h-[22rem] px-1" fadeBottom={28} maskRadius={12}>
          <ul className="grid grid-cols-4 gap-2 py-1 sm:grid-cols-5">
            <li>
              <button
                type="button"
                onClick={() => onChoose(null)}
                aria-pressed={chosenCoverCardId === null}
                className={`flex aspect-[2.5/3.5] cursor-pointer flex-col items-center justify-center gap-1.5 bg-white/[0.05] px-1 text-center ${TILE_BASE} ${FOCUS_RING_INSET} ${
                  chosenCoverCardId === null
                    ? "ring-2 ring-accent"
                    : "ring-white/10 hover:bg-white/[0.09]"
                }`}
              >
                <ImageIcon className="h-5 w-5 text-white/55" />
                <span className="text-[11px] font-medium leading-tight text-white/70">
                  Automatic
                </span>
                {chosenCoverCardId === null && <SelectedTick />}
              </button>
            </li>

            {choices.map(({ card }) => {
              const chosen = card.cardId === chosenCoverCardId;
              return (
                <li key={card.cardId}>
                  <button
                    type="button"
                    onClick={() => onChoose(card.cardId)}
                    aria-pressed={chosen}
                    aria-label={`Use ${card.name} as the deck cover`}
                    className={`cursor-pointer ${TILE_BASE} ${FOCUS_RING_INSET} ${
                      chosen ? "ring-2 ring-accent" : "ring-white/10 hover:ring-white/30"
                    }`}
                  >
                    <div className="aspect-[2.5/3.5] w-full">
                      <CardImage
                        fill
                        imageUrl={cardImageUrl(card.cardId, "low")}
                        alt={card.name}
                        className="h-full w-full object-cover"
                      />
                    </div>
                    {chosen && <SelectedTick />}
                  </button>
                </li>
              );
            })}
          </ul>
        </ScrollArea>

        {choices.length === 0 && (
          <p className="py-6 text-center text-sm text-white/55">
            Add some cards and one of them can front this deck.
          </p>
        )}

        <div className="mt-4 flex justify-end">
          <button type="button" onClick={onClose} className={GLASS_DIALOG_GHOST_BUTTON}>
            Done
          </button>
        </div>
      </div>
    </dialog>
  );
}

/** The chosen tile's corner tick — aria-hidden, since the button already says
    so through `aria-pressed`. */
function SelectedTick() {
  return (
    <span
      aria-hidden
      className="absolute right-1 top-1 inline-flex h-5 w-5 items-center justify-center rounded-full bg-accent text-zinc-950 shadow-[0_2px_8px_rgba(0,0,0,0.45)]"
    >
      <CheckIcon className="h-3 w-3" />
    </span>
  );
}

// The canonical domain Card (D5 — docs/workstreams/backend-data.md §5.2).
//
// MODELING CHOICE — one flat object, not the tcgdex discriminated union: the
// D1 rows (§5.3) already flatten the three categories into one table where
// every category-specific column is NULL off-category, and the read API
// serves that reality verbatim. Consumers still narrow on `category`; a flat
// shape just spares them a union round-trip for fields that are `null`
// either way. Nullability mirrors the DB exactly: TEXT/INTEGER nullable
// columns → `.nullable()`, NOT NULL columns → required.
//
// ASSET CONVENTION — `image` is OUR asset base path, `/assets/cards/{id}`
// (or null when the card has no scan). Clients append `/{quality}.{ext}`
// with quality ∈ high|low and ext ∈ webp|png|jpg — the same suffix rule as
// tcgdex origin URLs (§4.4) — and the Worker's GET /assets/cards/:id/:file
// route mirrors + serves the bytes. tcgdex origin URLs never leave the API.

import { z } from "zod";
import { legalSchema } from "./common";

export const cardCategorySchema = z.enum(["Pokemon", "Trainer", "Energy"]);
export type CardCategory = z.infer<typeof cardCategorySchema>;

/** The nine types Basic Energy cards have been printed for, in the canonical
    wheel order — the one basic-energy vocabulary of the monorepo (the engine
    derives energy provision from it, the deck builder its type palette).
    Fairy is retired (Sword & Shield era) but its prints remain in the pool.
    Dragon and Colorless are deliberately NOT here: both appear as cost/type
    entries, but Dragon has no Basic Energy and Colorless is a cost symbol,
    not an attachable basic type. */
export const BASIC_ENERGY_TYPES = [
  "Grass",
  "Fire",
  "Water",
  "Lightning",
  "Psychic",
  "Fighting",
  "Darkness",
  "Metal",
  "Fairy",
] as const;
export type BasicEnergyType = (typeof BASIC_ENERGY_TYPES)[number];

// The nested blocks persist as JSON columns typed with the tcgdex shapes, so
// these domain twins are structurally identical to their Tcgdex* namesakes —
// stored JSON round-trips through them unchanged.

/** An attack. `damage` is a number OR a modifier string ("60+", "20×"). */
export const attackSchema = z.object({
  cost: z.array(z.string()).optional(),
  name: z.string(),
  effect: z.string().optional(),
  damage: z.union([z.number(), z.string()]).optional(),
});
export type Attack = z.infer<typeof attackSchema>;

/** An ability block (`type` is "Ability", or era labels like "Poke-POWER"). */
export const abilitySchema = z.object({
  type: z.string().optional(),
  name: z.string(),
  effect: z.string().optional(),
});
export type Ability = z.infer<typeof abilitySchema>;

/** A weakness or resistance. `value` is a modifier string: "×2", "+20", "-30". */
export const weakResSchema = z.object({
  type: z.string(),
  value: z.string().optional(),
});
export type WeakRes = z.infer<typeof weakResSchema>;

/** Which print runs a card exists in. */
export const variantsSchema = z.object({
  normal: z.boolean().optional(),
  reverse: z.boolean().optional(),
  holo: z.boolean().optional(),
  firstEdition: z.boolean().optional(),
  wPromo: z.boolean().optional(),
});
export type Variants = z.infer<typeof variantsSchema>;

/** List/search projection of a card — what GET /cards and `set.cards` serve.
    Beyond identity + art it carries exactly the flat card-table columns the
    deck builder's tiles and client-side "kind" filters read (M9), plus the
    `legal` block the deck validator needs on hydrated lists (P2): energy
    types, hp, regulation mark and the per-category subtype discriminators.
    No JSON blobs (attacks/abilities/…) and no set join — those stay on the
    full Card / future projections. */
export const cardBriefSchema = z.object({
  id: z.string(),
  name: z.string(),
  category: cardCategorySchema,
  rarity: z.string().nullable(),
  /** OUR asset base path `/assets/cards/{id}` (append `/{quality}.{ext}`), or null. */
  image: z.string().nullable(),
  setId: z.string(),
  localId: z.string(),
  /** Energy types, e.g. ["Grass"] (Pokémon only). */
  types: z.array(z.string()).nullable(),
  hp: z.number().int().nullable(),
  regulationMark: z.string().nullable(),
  /** Pokémon stage, tcgdex vocabulary ("Basic" | "Stage1" | "Stage2" | …). */
  stage: z.string().nullable(),
  /** Trainer subtype ("Item" | "Supporter" | "Stadium" | "Tool" | …). */
  trainerType: z.string().nullable(),
  /** Energy subtype ("Normal" | "Special"). */
  energyType: z.string().nullable(),
  legal: legalSchema,
});
export type CardBrief = z.infer<typeof cardBriefSchema>;

/** The one canonical Card (D5) — everything the catalog persists for a card. */
export const cardSchema = z.object({
  /** tcgdex id, e.g. "sv06.5-001" — our canonical card id. */
  id: z.string(),
  setId: z.string(),
  localId: z.string(),
  name: z.string(),
  category: cardCategorySchema,
  /** OUR asset base path `/assets/cards/{id}` (append `/{quality}.{ext}`), or null. */
  image: z.string().nullable(),
  illustrator: z.string().nullable(),
  rarity: z.string().nullable(),
  regulationMark: z.string().nullable(),

  // Pokémon-only (null on Trainer/Energy).
  hp: z.number().int().nullable(),
  stage: z.string().nullable(),
  evolveFrom: z.string().nullable(),
  /** Energy types, e.g. ["Grass"]. */
  types: z.array(z.string()).nullable(),
  retreat: z.number().int().nullable(),
  abilities: z.array(abilitySchema).nullable(),
  attacks: z.array(attackSchema).nullable(),
  weaknesses: z.array(weakResSchema).nullable(),
  resistances: z.array(weakResSchema).nullable(),

  // Trainer/Energy-only.
  trainerType: z.string().nullable(),
  energyType: z.string().nullable(),
  /** Trainer/Energy rules text (null on basic energies and all Pokémon). */
  effect: z.string().nullable(),

  legal: legalSchema,
  variants: variantsSchema.nullable(),
});
export type Card = z.infer<typeof cardSchema>;

// Card model + metadata for the deck builder. The card *data* comes from the
// live catalog api (fetched by useCardSearch, adapted in catalog.ts); this
// module holds the types, the energy-type palette, the format definitions,
// and small pure helpers shared across the builder. Kept pixi-free and
// side-effect-free so the pure logic (deckMath, decklistText) and their
// tests can import it freely.

import { BASIC_ENERGY_TYPES, type BasicEnergyType } from "@luminous/schema";
import { ENERGY_COLORS } from "../../lib/energyPalette";

/** The energy types the builder filters and paints, in the canonical wheel
    order. Derived from the shared basic-energy vocabulary (@luminous/schema)
    minus the retired Fairy — old Fairy prints keep adapting to typeless
    tiles rather than growing a palette entry — plus Dragon (a Pokémon type
    with no Basic Energy) and Colorless (a cost symbol), which exist only in
    this UI palette. */
export type EnergyType = Exclude<BasicEnergyType, "Fairy"> | "Dragon" | "Colorless";

export const ENERGY_TYPES: readonly EnergyType[] = [
  ...BASIC_ENERGY_TYPES.filter(
    (type): type is Exclude<BasicEnergyType, "Fairy"> => type !== "Fairy",
  ),
  "Dragon",
  "Colorless",
];

/** Top-level card category — drives the deck-list grouping (Pokémon / Trainer /
    Energy) and the right-panel split. Uses the accented "Pokémon" spelling the
    game itself uses. */
export type Supertype = "Pokémon" | "Trainer" | "Energy";

export const SUPERTYPES: Supertype[] = ["Pokémon", "Trainer", "Energy"];

// NOTE (P2 task 10): the printed-subtype and rarity vocabularies used to be
// hardcoded tuples here (POKEMON_STAGES, TRAINER_SUBTYPES, RARITIES, …). They
// now come from the live catalog — GET /facets via useCatalogOptions — so a
// card's `subtype` and `rarity` stay plain strings and the rail's chips
// reflect what is actually ingested.

/** A single browsable card — the builder's view of a catalog card (adapted
    from the api shapes in catalog.ts). `cardId` is the tcgdex id ("sv06.5-001"),
    also the key of the api's art mirror. Optional fields are absent for
    categories they don't apply to (a Trainer has no `types`/`hp`, an Energy
    no `hp`, etc.). */
export interface BuilderCard {
  cardId: string;
  name: string;
  supertype: Supertype;
  /** Basic | Stage 1 | Stage 2 | Item | Supporter | Stadium | Pokémon Tool |
      Basic Energy | Special Energy — or a newer printed subtype the catalog
      knows and this build's tuples don't. */
  subtype: string;
  /** Energy type(s) — Pokémon (its type) and most Energy cards. */
  types?: EnergyType[];
  hp?: number;
  /** Regulation mark (e.g. "H", "I"), the basis of Standard-format legality. */
  regulationMark?: string;
  /** Exact catalog rarity string, e.g. "Double rare". */
  rarity?: string;
  /** Collector number within its set (the catalog's localId, e.g. "081"). */
  number?: string;
  /** Whether the catalog has a scan for this card — when false, tiles render
      the neutral fallback instead of requesting art that would 404. */
  hasImage?: boolean;
  /** The catalog's structured format-legality verdict (P2) — present on every
      api-adapted card; optional only for hand-built fixtures. Groundwork for
      validateDeck to stop inferring legality from regulation marks. */
  legal?: { standard: boolean; expanded: boolean };
}

