1	import { useEffect, useId, useRef } from "react";
2	import { CardImage } from "../../../components/CardImage";
3	import { CheckIcon, ImageIcon, XIcon } from "../../../components/icons";
4	import { ScrollArea } from "../../../components/ScrollArea";
5	import { cardImageUrl } from "../../../lib/api";
6	import {
7	  FOCUS_RING_INSET,
8	  GLASS_DIALOG_GHOST_BUTTON,
9	  GLASS_DIALOG_PANEL,
10	} from "../../../lib/glass";
11	import type { Deck } from "../deckMath";
12	
13	// Which card fronts this deck in the library (P5-6 — the follow-up P5-3 left
14	// room for). The derived default is a heuristic ("the biggest Pokémon") and will
15	// sometimes pick the wall over the attacker beside it; here the owner overrules
16	// it, which is the only answer that is always right.
17	//
18	// AUTOMATIC IS AN EXPLICIT OPTION, not the absence of a choice, so going back to
19	// it is one click rather than a thing you cannot express. It leads the grid, and
20	// deliberately shows no card art: the default is a RULE, and drawing today's
21	// answer to it would read as "this card", which is exactly what it isn't.
22	//
23	// Picking applies immediately — like every other edit in this editor, it rides
24	// the debounced save — so the dialog needs no Save button, only a way out.
25	
26	export interface CoverDialogProps {
27	  open: boolean;
28	  /** The deck's HYDRATED entries — the cards there is art to choose from. */
29	  deck: Deck;
30	  /** The owner's current pick, or null for the derived default. */
31	  chosenCoverCardId: string | null;
32	  /** Pin a card id, or null to go back to automatic. */
33	  onChoose: (cardId: string | null) => void;
34	  onClose: () => void;
35	}
36	
37	const TILE_BASE =
38	  "relative block w-full overflow-hidden rounded-lg ring-1 ring-inset transition-all hover:scale-[1.03] active:scale-95";
39	
40	export function CoverDialog({
41	  open,
42	  deck,
43	  chosenCoverCardId,
44	  onChoose,
45	  onClose,
46	}: CoverDialogProps) {
47	  const dialogRef = useRef<HTMLDialogElement>(null);
48	  const titleId = useId();
49	
50	  // Native <dialog> driven by `open`, exactly like ImportExportDialog: focus
51	  // move-in, focus trapping, Escape and focus restoration for free.
52	  useEffect(() => {
53	    const dialog = dialogRef.current;
54	    if (!dialog) return;
55	    if (open && !dialog.open) dialog.showModal();
56	    else if (!open && dialog.open) dialog.close();
57	  }, [open]);
58	
59	  // Only cards the catalog can draw: a cover with no scan is a blank rectangle,
60	  // and the server resolves such a pin back to the default anyway.
61	  const choices = deck.filter(({ card }) => card.hasImage);
62	
63	  return (
64	    // biome-ignore lint/a11y/useKeyWithClickEvents: the native <dialog> handles Escape; this onClick only adds backdrop click-to-dismiss for pointer users.
65	    <dialog
66	      ref={dialogRef}
67	      aria-labelledby={titleId}
68	      onClose={onClose}
69	      onClick={(e) => {
70	        // A click whose target is the dialog itself landed on the ::backdrop.
71	        if (e.target === dialogRef.current) onClose();
72	      }}
73	      className="m-auto border-0 bg-transparent p-0 text-white [&::backdrop]:bg-black/60 [&::backdrop]:backdrop-blur-sm"
74	    >
75	      <div className={`w-[min(34rem,calc(100vw-2rem))] ${GLASS_DIALOG_PANEL}`}>
76	        <div className="mb-1 flex items-center justify-between">
77	          <h2 id={titleId} className="text-base font-semibold text-white/90">
78	            Deck cover
79	          </h2>
80	          <button
81	            type="button"
82	            aria-label="Close"
83	            onClick={onClose}
84	            className={`flex h-8 w-8 cursor-pointer items-center justify-center rounded-full text-white/55 transition-colors hover:bg-white/10 hover:text-white ${FOCUS_RING_INSET}`}
85	          >
86	            <XIcon className="h-4 w-4" />
87	          </button>
88	        </div>
89	
90	        <p className="mb-3 text-xs text-white/55">
91	          The card that fronts this deck in your library.
92	        </p>
93	
94	        <ScrollArea className="-mx-1 max-h-[22rem] px-1" fadeBottom={28} maskRadius={12}>
95	          <ul className="grid grid-cols-4 gap-2 py-1 sm:grid-cols-5">
96	            <li>
97	              <button
98	                type="button"
99	                onClick={() => onChoose(null)}
100	                aria-pressed={chosenCoverCardId === null}
101	                className={`flex aspect-[2.5/3.5] cursor-pointer flex-col items-center justify-center gap-1.5 bg-white/[0.05] px-1 text-center ${TILE_BASE} ${FOCUS_RING_INSET} ${
102	                  chosenCoverCardId === null
103	                    ? "ring-2 ring-accent"
104	                    : "ring-white/10 hover:bg-white/[0.09]"
105	                }`}
106	              >
107	                <ImageIcon className="h-5 w-5 text-white/55" />
108	                <span className="text-[11px] font-medium leading-tight text-white/70">
109	                  Automatic
110	                </span>
111	                {chosenCoverCardId === null && <SelectedTick />}
112	              </button>
113	            </li>
114	
115	            {choices.map(({ card }) => {
116	              const chosen = card.cardId === chosenCoverCardId;
117	              return (
118	                <li key={card.cardId}>
119	                  <button
120	                    type="button"
121	                    onClick={() => onChoose(card.cardId)}
122	                    aria-pressed={chosen}
123	                    aria-label={`Use ${card.name} as the deck cover`}
124	                    className={`cursor-pointer ${TILE_BASE} ${FOCUS_RING_INSET} ${
125	                      chosen ? "ring-2 ring-accent" : "ring-white/10 hover:ring-white/30"
126	                    }`}
127	                  >
128	                    <div className="aspect-[2.5/3.5] w-full">
129	                      <CardImage
130	                        fill
131	                        imageUrl={cardImageUrl(card.cardId, "low")}
132	                        alt={card.name}
133	                        className="h-full w-full object-cover"
134	                      />
135	                    </div>
136	                    {chosen && <SelectedTick />}
137	                  </button>
138	                </li>
139	              );
140	            })}
141	          </ul>
142	        </ScrollArea>
143	
144	        {choices.length === 0 && (
145	          <p className="py-6 text-center text-sm text-white/55">
146	            Add some cards and one of them can front this deck.
147	          </p>
148	        )}
149	
150	        <div className="mt-4 flex justify-end">
151	          <button type="button" onClick={onClose} className={GLASS_DIALOG_GHOST_BUTTON}>
152	            Done
153	          </button>
154	        </div>
155	      </div>
156	    </dialog>
157	  );
158	}
159	
160	/** The chosen tile's corner tick — aria-hidden, since the button already says
161	    so through `aria-pressed`. */
162	function SelectedTick() {
163	  return (
164	    <span
165	      aria-hidden
166	      className="absolute right-1 top-1 inline-flex h-5 w-5 items-center justify-center rounded-full bg-accent text-zinc-950 shadow-[0_2px_8px_rgba(0,0,0,0.45)]"
167	    >
168	      <CheckIcon className="h-3 w-3" />
169	    </span>
170	  );
171	}
