1	// The typed client for the api Worker (backend-data.md §6) — the ONE module
2	// features go through to talk to the backend over http. Every URL derives
3	// from apiOrigin.ts, every request sends the session cookie (`credentials:
4	// "include"` — the cookie is SameSite=None and the api is cross-origin), and
5	// every non-2xx becomes a typed ApiError so features can branch on `.status`.
6	//
7	// TYPES-ONLY by design: this module imports nothing but types from
8	// @luminous/schema — no zod, no runtime schema values — so the web bundle
9	// stays zod-free (the same constraint that split zod off the online chunk in
10	// M8). The api already boundary-parses everything it serves; the client
11	// trusts the wire and casts to the shared types.
12	
13	import type {
14	  Card,
15	  CardBrief,
16	  CardCategory,
17	  CatalogFacets,
18	  CreateDeckRequest,
19	  CreateFolderRequest,
20	  Deck,
21	  DeckSummary,
22	  Folder,
23	  LoginRequest,
24	  Paginated,
25	  PatchDeckRequest,
26	  PatchFolderRequest,
27	  RegisterRequest,
28	  ReorderRequest,
29	  Serie,
30	  SetBrief,
31	  SetWithCards,
32	  UpdateProfileRequest,
33	  User,
34	} from "@luminous/schema";
35	import { apiUrl } from "./apiOrigin";
36	
37	/** A non-2xx api response. `status` is the http status; `body` is the parsed
38	    JSON error payload when the api sent one (terse `{error}` objects, plus
39	    extras like the 400 `cardIds` list), else undefined. Notable statuses:
40	    401 logged out · 404 absent/not-yours · 409 duplicate email · 429
41	    rate-limited · 503 OAuth not configured. */
42	export class ApiError extends Error {
43	  readonly status: number;
44	  readonly body: unknown;
45	
46	  constructor(status: number, body: unknown) {
47	    const detail =
48	      typeof body === "object" && body !== null && "error" in body
49	        ? String((body as { error: unknown }).error)
50	        : `request failed with status ${status}`;
51	    super(detail);
52	    this.name = "ApiError";
53	    this.status = status;
54	    this.body = body;
55	  }
56	}
57	
58	/** The api's 400 `{error: "unknown card id(s)", cardIds}` payload, if that's
59	    what an ApiError's `.body` is — the ids the catalog rejected. */
60	export function unknownCardIdsOf(body: unknown): string[] | null {
61	  if (typeof body !== "object" || body === null || !("cardIds" in body)) return null;
62	  const ids = (body as { cardIds: unknown }).cardIds;
63	  return Array.isArray(ids) && ids.every((id) => typeof id === "string") ? ids : null;
64	}
65	
66	// ---- Session recovery (the ONE owner of 401 → re-probe → retry-once) --------
67	// A mid-session 401 usually means the cookie expired, but it can also be a
68	// one-off (a session rotated in another tab, a hiccup). Instead of every
69	// feature hand-rolling "on 401, refresh() the auth context", the client owns
70	// it: an unexpected 401 asks the installed handler to re-probe the session,
71	// and if the session turns out to still be alive the failed request is
72	// retried once. When the probe lands on signed-out, the handler's own state
73	// change (AuthProvider → "anonymous") flips the UI; the 401 then propagates
74	// to the caller as before.
75	
76	/** Re-probe the session; resolve true when it's still alive (retry the
77	    request), false when the user is really signed out. */
78	type SessionRecoveryHandler = () => Promise<boolean>;
79	
80	let recoverSession: SessionRecoveryHandler | null = null;
81	/** In-flight probe, shared so a burst of parallel 401s asks once. */
82	let recovery: Promise<boolean> | null = null;
83	
84	/** Installed by AuthProvider (null on teardown). One owner at a time. */
85	export function setSessionRecoveryHandler(handler: SessionRecoveryHandler | null): void {
86	  recoverSession = handler;
87	}
88	
89	function attemptRecovery(): Promise<boolean> {
90	  const handler = recoverSession;
91	  if (handler === null) return Promise.resolve(false);
92	  recovery ??= handler().then(
93	    (alive) => {
94	      recovery = null;
95	      return alive;
96	    },
97	    () => {
98	      recovery = null;
99	      return false;
100	    },
101	  );
102	  return recovery;
103	}
104	
105	/** The one fetch wrapper every call goes through: cookie on every request,
106	    JSON in/out, non-2xx → ApiError, 204 → undefined. A 401 anywhere but
107	    /auth/* runs the session-recovery hook above and retries once — /auth is
108	    excluded because there a 401 IS the answer (me() = signed out, login =
109	    wrong credentials), and because the recovery probe itself is /auth/me. */
110	async function request<T>(path: string, init?: { method?: string; body?: unknown }): Promise<T> {
111	  let response = await send(path, init);
112	  if (response.status === 401 && !path.startsWith("/auth/") && (await attemptRecovery())) {
113	    response = await send(path, init);
114	  }
115	  if (!response.ok) throw new ApiError(response.status, await errorBody(response));
116	  if (response.status === 204) return undefined as T;
117	  return (await response.json()) as T;
118	}
119	
120	function send(path: string, init?: { method?: string; body?: unknown }): Promise<Response> {
121	  const hasBody = init?.body !== undefined;
122	  return fetch(apiUrl(path), {
123	    method: init?.method ?? "GET",
124	    credentials: "include",
125	    headers: hasBody ? { "content-type": "application/json" } : undefined,
126	    body: hasBody ? JSON.stringify(init?.body) : undefined,
127	  });
128	}
129	
130	/** The parsed error payload, or undefined when it isn't JSON (proxies and
131	    the runtime itself can answer with plain-text error pages). */
132	async function errorBody(response: Response): Promise<unknown> {
133	  if (!response.headers.get("content-type")?.includes("application/json")) return undefined;
134	  try {
135	    return await response.json();
136	  } catch {
137	    return undefined;
138	  }
139	}
140	
141	/** `?key=value…` from the defined, non-empty params — or "" when none
142	    survive, so an unfiltered call hits the bare path. An array value emits
143	    one occurrence per non-empty item (`?type=Fire&type=Water`) — the api's
144	    repeatable-param convention; an empty array is omitted entirely. */
145	function queryString(params: Record<string, string | number | string[] | undefined>): string {
146	  const search = new URLSearchParams();
147	  for (const [key, value] of Object.entries(params)) {
148	    if (value === undefined || value === "") continue;
149	    if (Array.isArray(value)) {
150	      for (const item of value) {
151	        if (item !== "") search.append(key, item);
152	      }
153	    } else {
154	      search.append(key, String(value));
155	    }
156	  }
157	  const encoded = search.toString();
158	  return encoded === "" ? "" : `?${encoded}`;
159	}
