14	/** A vertical scroll box whose scrollbar is a custom overlay rendered OUTSIDE
15	    the scrolling content — a single draggable thumb floating in the right
16	    gutter. Because it's absolutely positioned the native bar is hidden
17	    (`.scrollbar-none` in scrollArea.css) and the content never reflows to make
18	    room for it. Wheel/trackpad/keyboard still drive the real overflow. */
19	export function ScrollArea({
20	  children,
21	  className,
22	  outerClassName,
23	  trackTop = 0,
24	  trackBottom = 0,
25	  fadeTop = 0,
26	  fadeBottom = 0,
27	  maskRadius = 0,
28	  fadeTopOnScroll = false,
29	}: {
30	  children: ReactNode;
31	  /** Applied to the scrolling element (padding, negative margins, etc.). */
32	  className?: string;
33	  /** Applied to the outer wrapper — use for spacing that should sit OUTSIDE the
34	      scroll (e.g. a fixed gap below the toolbar that doesn't scroll away). */
35	  outerClassName?: string;
36	  /** Inset (px) of the scrollbar from the top/bottom of the viewport, so it can
37	      line up with the content (e.g. start at the first card, not the top
38	      padding) instead of spanning the raw scroll box. */
39	  trackTop?: number;
40	  trackBottom?: number;
41	  /** Height (px) of a soft fade-out at the top edge, so content dissolves to
42	      transparent as it scrolls up under whatever sits above (e.g. a search bar)
43	      instead of hard-cutting. Rendered by a fragment shader (see
44	      {@link fadeMaskDataUrl}) into the viewport's `mask-image`. */
45	  fadeTop?: number;
46	  /** Like {@link fadeTop}, but feathering the bottom edge. */
47	  fadeBottom?: number;
48	  /** Corner radius (px) of the masked viewport, so the scroll box clips on soft
