54	      The bottom feather ({@link fadeBottom}) is unaffected. */
55	  fadeTopOnScroll?: boolean;
56	}) {
57	  const scrollRef = useRef<HTMLDivElement>(null);
58	  const contentRef = useRef<HTMLDivElement>(null);
59	  const drag = useRef<{ pointerY: number; scrollTop: number } | null>(null);
60	  // Last baked edge-mask signature (size + params) — so the shader only re-bakes
61	  // when the box actually changes, never on every scroll event.
62	  const maskKey = useRef("");
63	  // Baked masks keyed by `${w}x${h}:${fadeTop},${fadeBottom},${radius}`. With a
64	  // scroll-driven top feather the top value steps through a handful of quantized
65	  // values, so caching avoids re-baking (toDataURL) once each has been seen.
66	  const maskCache = useRef<Map<string, string>>(new Map());
67	  const [thumb, setThumb] = useState({ height: 0, top: 0, shown: false });
68	
69	  // Recompute the thumb's size/offset (relative to the rail) from scroll metrics.
70	  // The thumb travels the full inset track — flush to the top, no arrow zones.
71	  const measure = useCallback(() => {
72	    const el = scrollRef.current;
73	    if (!el) return;
74	    const { scrollTop, scrollHeight, clientHeight, clientWidth } = el;
75	    // Edge mask (rounded corners + top/bottom feather), drawn by a fragment
76	    // shader. It's pinned to the viewport — independent of scroll — so it only
77	    // (re)bakes when the box size or params change, never per scroll frame.
78	    // With fadeTopOnScroll the top feather grows from 0 (flush, crisp first row)
79	    // to `fadeTop` over the first `fadeTop` px of scroll, quantized to 4px steps so
80	    // only a handful of distinct masks are ever baked (then cached below).
81	    const effFadeTop = fadeTopOnScroll
82	      ? Math.round(Math.min(fadeTop, Math.max(0, scrollTop)) / 4) * 4
83	      : fadeTop;
84	    if (effFadeTop > 0 || fadeBottom > 0 || maskRadius > 0) {
85	      const key = `${clientWidth}x${clientHeight}:${effFadeTop},${fadeBottom},${maskRadius}`;
86	      if (key !== maskKey.current && clientWidth > 0 && clientHeight > 0) {
87	        maskKey.current = key;
88	        let url = maskCache.current.get(key);
89	        if (url === undefined) {
90	          url =
91	            fadeMaskDataUrl({
92	              width: clientWidth,
93	              height: clientHeight,
94	              fadeTop: effFadeTop,
95	              fadeBottom,
96	              radius: maskRadius,
97	            }) ?? "";
98	          maskCache.current.set(key, url);
99	        }
100	        if (url) {
101	          el.style.maskImage = `url("${url}")`;
102	          el.style.setProperty("-webkit-mask-image", `url("${url}")`);
103	          el.style.maskSize = "100% 100%";
104	          el.style.setProperty("-webkit-mask-size", "100% 100%");
105	          el.style.maskRepeat = "no-repeat";
106	          el.style.setProperty("-webkit-mask-repeat", "no-repeat");
107	        } else if (effFadeTop > 0) {
108	          // No WebGL — fall back to a plain CSS gradient top feather.
109	          const grad = `linear-gradient(to bottom, transparent, #000 ${effFadeTop}px)`;
110	          el.style.maskImage = grad;
111	          el.style.setProperty("-webkit-mask-image", grad);
112	        }
113	      }
114	    }
115	    if (scrollHeight <= clientHeight + 1) {
116	      setThumb((t) => (t.shown ? { ...t, shown: false } : t));
117	      return;
118	    }
119	    const travel = Math.max(clientHeight - trackTop - trackBottom, MIN_THUMB);
120	    const height = Math.max((clientHeight / scrollHeight) * travel, MIN_THUMB);
121	    const top = (scrollTop / (scrollHeight - clientHeight)) * (travel - height);
122	    setThumb({ height, top, shown: true });
123	  }, [trackTop, trackBottom, fadeTop, fadeBottom, maskRadius, fadeTopOnScroll]);
124	
125	  // Track scroll position and any size change (viewport or content growth).
126	  useEffect(() => {
127	    const el = scrollRef.current;
128	    const content = contentRef.current;
129	    if (!el || !content) return;
130	    measure();
131	    el.addEventListener("scroll", measure, { passive: true });
132	    const ro = new ResizeObserver(measure);
133	    ro.observe(el);
134	    ro.observe(content);
135	    return () => {
136	      el.removeEventListener("scroll", measure);
137	      ro.disconnect();
138	    };
139	  }, [measure]);
140	
141	  // Dragging the thumb maps pointer travel back onto scrollTop.
142	  useEffect(() => {
143	    const onMove = (e: PointerEvent) => {
144	      const d = drag.current;
145	      const el = scrollRef.current;
146	      if (!d || !el) return;
147	      const { scrollHeight, clientHeight } = el;
148	      const travel = Math.max(clientHeight - trackTop - trackBottom, MIN_THUMB);
149	      const height = Math.max((clientHeight / scrollHeight) * travel, MIN_THUMB);
150	      const trackRange = travel - height;
151	      if (trackRange <= 0) return;
152	      const scrollRange = scrollHeight - clientHeight;
153	      el.scrollTop = d.scrollTop + ((e.clientY - d.pointerY) / trackRange) * scrollRange;
154	    };
155	    const onUp = () => {
156	      if (!drag.current) return;
157	      drag.current = null;
158	      document.body.style.userSelect = "";
159	    };
160	    window.addEventListener("pointermove", onMove);
161	    window.addEventListener("pointerup", onUp);
162	    return () => {
163	      window.removeEventListener("pointermove", onMove);
164	      window.removeEventListener("pointerup", onUp);
165	    };
166	  }, [trackTop, trackBottom]);
167	
168	  const startDrag = (e: ReactPointerEvent) => {
169	    const el = scrollRef.current;
170	    if (!el) return;
171	    drag.current = { pointerY: e.clientY, scrollTop: el.scrollTop };
172	    document.body.style.userSelect = "none";
173	  };
174	
175	  return (
176	    <div className={`relative min-h-0 flex-1${outerClassName ? ` ${outerClassName}` : ""}`}>
177	      <div
178	        ref={scrollRef}
179	        className={`scrollbar-none h-full overflow-y-auto overflow-x-hidden${className ? ` ${className}` : ""}`}
180	      >
181	        <div ref={contentRef}>{children}</div>
182	      </div>
183	      {/* Scrollbar rail in the right gutter — outside the scroll box, so it never
184	          eats content width. Inset to the track span so it lines up with the
185	          content; a single thumb fills it, starting flush at the top. */}
186	      <div
187	        style={{ top: trackTop, bottom: trackBottom }}
188	        className={`pointer-events-none absolute -right-5 w-3 transition-opacity duration-150 ${
189	          thumb.shown ? "opacity-100" : "opacity-0"
190	        }`}
191	      >
192	        <div
193	          aria-hidden
194	          onPointerDown={startDrag}
195	          style={{ height: thumb.height, transform: `translate(-50%, ${thumb.top}px)` }}
196	          className="pointer-events-auto absolute left-1/2 top-0 w-1.5 cursor-grab rounded-full bg-white/20 transition-colors duration-150 hover:bg-white/30 active:cursor-grabbing active:bg-white/40"
197	        />
198	      </div>
199	    </div>
200	  );
201	}
