1	import { useState } from "react";
2	
3	const CARD_ASPECT_RATIO = 3.5 / 2.5;
4	
5	interface CardImageProps {
6	  imageUrl?: string;
7	  alt: string;
8	  priority?: boolean;
9	  className?: string;
10	  /** Fixed-size mode (the playmat): renders explicit width/height attributes so
11	      layout never shifts as art loads. Provide this OR set `fill`. */
12	  renderedWidth?: number;
13	  /** Fluid mode (the deck builder grid): the parent owns the box (e.g. an
14	      aspect-ratio container) and the image fills it. `className` should carry the
15	      object-fit + size utilities. */
16	  fill?: boolean;
17	}
18	
19	/** A card image with a graceful fallback: when there's no source, or the remote
20	    art 404s / fails CORS, it renders a neutral correctly-shaped tile instead of
21	    the browser's broken-image glyph. Works in two layouts — fixed (px width) for
22	    the simulator, or `fill` for a responsive grid cell. */
23	export function CardImage({
24	  imageUrl,
25	  renderedWidth,
26	  alt,
27	  priority = false,
28	  className,
29	  fill = false,
30	}: CardImageProps) {
31	  const loading = priority ? "eager" : "lazy";
32	  const fetchPriority = priority ? "high" : "auto";
33	  // Track the URL that failed (not just a boolean) so a later prop change to a
34	  // different imageUrl re-attempts the load instead of staying on the fallback.
35	  const [failedUrl, setFailedUrl] = useState<string | null>(null);
36	
37	  // Fixed mode sizes the element itself; fluid mode leaves sizing to the parent.
38	  const sized =
39	    !fill && renderedWidth !== undefined
40	      ? { width: Math.round(renderedWidth), height: Math.round(renderedWidth * CARD_ASPECT_RATIO) }
41	      : undefined;
42	
43	  if (!imageUrl || failedUrl === imageUrl) {
44	    return (
45	      <div
46	        className={className}
47	        style={{ ...(sized ?? {}), background: "#161621" }}
48	        aria-label={alt}
49	        role="img"
50	      />
51	    );
52	  }
53	
54	  return (
55	    <img
56	      src={imageUrl}
57	      alt={alt}
58	      width={sized?.width}
59	      height={sized?.height}
60	      loading={loading}
61	      decoding="async"
62	      fetchPriority={fetchPriority}
63	      referrerPolicy="no-referrer"
64	      className={className}
65	      style={{ imageRendering: "auto", display: "block" }}
66	      draggable={false}
67	      onError={() => setFailedUrl(imageUrl)}
68	    />
69	  );
70	}
