$AB eval '(()=>{
  const clickables=[...document.querySelectorAll("a,button,[role=\"button\"],[role=\"link\"]")].map(el=>({tag:el.tagName,role:el.getAttribute("role"),href:el.getAttribute("href"),aria:el.getAttribute("aria-label"),t:(el.textContent||"").trim().slice(0,40)}));
  return JSON.stringify(clickables.slice(0,30));
})()' 2>&1 | tail -3

AB=/etc/profiles/per-user/jofre/bin/agent-browser
$AB eval '(()=>{
  const info=[...document.querySelectorAll("button[aria-label^=\"View \"]")];
  const add=[...document.querySelectorAll("button[aria-label^=\"Add \"]")];
  // deck total: find the deck-count readout (look for "cards" counter text)
  const first=info[0];
  return JSON.stringify({
    infoCount:info.length,
    firstInfoLabel:first&&first.getAttribute("aria-label"),
    firstInfoOpacity: first&&getComputedStyle(first).opacity,
    firstAddLabel: add[0]&&add[0].getAttribute("aria-label"),
    dialogOpen: !!document.querySelector("dialog[open]")
  });
})()' 2>&1 | tail -2

AB=/etc/profiles/per-user/jofre/bin/agent-browser
sleep 1
$AB eval '(()=>{
  const d=document.querySelector("dialog[open]"); if(!d) return "no dialog";
  const txt=(d.textContent||"").replace(/\s+/g," ").trim();
  const img=d.querySelector("img");
  const sections=[...d.querySelectorAll("h3")].map(h=>h.textContent.trim());
  return JSON.stringify({
    sections,
    hasIllus: /Illus\./.test(txt),
    setNumber: (txt.match(/[0-9]+ · [a-z0-9.]+/)||[])[0]||null,
    imgSrc: img&&img.getAttribute("src"),
    imgNaturalWidth: img&&img.naturalWidth,
    excerpt: txt.slice(0,220)
  });
})()' 2>&1 | tail -2

AB=/etc/profiles/per-user/jofre/bin/agent-browser
$AB eval '(()=>{const b=[...document.querySelectorAll("button[aria-label=\"View Academy at Night details\"]")][0]; return b?(b.click(),"clicked"):"missing";})()' 2>&1 | tail -1
sleep 2
$AB eval '(()=>{
  const d=document.querySelector("dialog[open]"); if(!d) return "no dialog";
  const txt=(d.textContent||"").replace(/\s+/g," ").trim();
  const sections=[...d.querySelectorAll("h3")].map(h=>h.textContent.trim());
  const h=d.querySelector("h2");
  return JSON.stringify({heading:h&&h.textContent, sections, hasAttacks:sections.includes("Attacks"), hasEffect:sections.includes("Effect"), excerpt:txt.slice(0,260)});
})()' 2>&1 | tail -2

